/**
 * Globals created by Google's gtag.js.
 * See src/components/GoogleAnalytics.tsx.
 */
interface Window {
  dataLayer?: unknown[];
  gtag?: (...args: unknown[]) => void;
  /** gtag.js kill switch, e.g. `window['ga-disable-G-XXXXXXX'] = true`. */
  [key: `ga-disable-${string}`]: boolean | undefined;
}

declare module '*.css';
declare module '*.scss';
declare module '*.sass';
declare module '*.mp3';
declare module '*.mp4';
